"xpert_project_pipeline_run","name":"PK_9f1d4dc694d4bcf76214cf4bb91","definition":"CREATE UNIQUE INDEX \"PK_9f1d4dc694d4bcf76214cf4bb91\" ON public.xpert_project_pipeline_run USING btree (id)","valid":true},{"table":"xpert_project_pipeline_task_link","name":"PK_45f2ace3c08364f0c7e506f225e","definition":"CREATE UNIQUE INDEX \"PK_45f2ace3c08364f0c7e506f225e\" ON public.xpert_project_pipeline_task_link USING btree (id)","valid":true},{"table":"xpert_project_task","name":"PK_403b3dfdf4c123566f85bcd1fc4","definition":"CREATE UNIQUE INDEX \"PK_403b3dfdf4c123566f85bcd1fc4\" ON public.xpert_project_task USING btree (id)","valid":true},{"table":"xpert_project_task_execution","name":"PK_a812f267da8e2992bda397426ad","definition":"CREATE UNIQUE INDEX \"PK_a812f267da8e2992bda397426ad\" ON public.xpert_project_task_execution USING btree (id)","valid":true},{"table":"xpert_task_execution","name":"PK_bab215d3b602648e3538c3e86c1","definition":"CREATE UNIQUE INDEX \"PK_bab215d3b602648e3538c3e86c1\" ON public.xpert_task_execution USING btree (id)","valid":true}]}$catalog$::jsonb AS catalog),
columns AS (
  SELECT c.relname AS "table", a.attname AS name, format_type(a.atttypid,a.atttypmod) AS type,
    a.attnotnull AS "notNull", pg_get_expr(d.adbin,d.adrelid) AS "default"
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
  WHERE n.nspname=current_schema() AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
),
constraints AS (
  SELECT t.relname AS "table", c.conname AS name, pg_get_constraintdef(c.oid) AS definition,
    c.convalidated AS validated FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
),
indexes AS (
  SELECT t.relname AS "table", c.relname AS name, pg_get_indexdef(i.indexrelid) AS definition, i.indisvalid AS valid
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
)
SELECT 'column:'||e."table"||'.'||e.name AS missing FROM expected,
  jsonb_to_recordset(catalog->'columns') AS e("table" text,name text,type text,"notNull" boolean,"default" text)
WHERE NOT EXISTS (SELECT 1 FROM columns a WHERE a."table"=e."table" AND a.name=e.name AND a.type=e.type
  AND a."notNull"=e."notNull" AND a."default" IS NOT DISTINCT FROM e."default")
UNION ALL
SELECT 'constraint:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'constraints') AS e("table" text,name text,definition text,validated boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM constraints a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.validated=e.validated)
UNION ALL
SELECT 'index:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'indexes') AS e("table" text,name text,definition text,valid boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM indexes a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.valid=e.valid)
) SELECT missing FROM structure_failures
UNION ALL
SELECT 'extension:' || required.name AS missing
FROM (VALUES ('pgcrypto'), ('vector')) AS required(name)
WHERE NOT EXISTS (SELECT 1 FROM pg_extension e WHERE e.extname=required.name)
UNION ALL
SELECT 'enum:' || required.name
FROM (VALUES
('xpert_project_task_execution_status_enum', ARRAY['queued', 'running', 'succeeded', 'failed', 'cancelled']::text[]),
('xpert_project_task_priority_enum', ARRAY['urgent', 'high', 'medium', 'low']::text[]),
('xpert_project_task_status_enum', ARRAY['todo', 'in_progress', 'review', 'paused', 'done', 'blocked', 'cancelled', 'pending', 'completed', 'failed']::text[])
) AS required(name, labels)
WHERE NOT EXISTS (
 SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace
 WHERE n.nspname=current_schema() AND t.typname=required.name
 AND (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)=required.labels
);
